os.close(slave)

buf = bytearray()

def pump(timeout=0.1):
    end = time.time() + timeout
    while time.time() < end:
        r, _, _ = select.select([master], [], [], min(0.05, max(0, end - time.time())))
        if not r:
            continue
        chunk = os.read(master, 65536)
        if not chunk:
            break
        buf.extend(chunk)

def send(data, wait=0.2):
    os.write(master, data)
    pump(wait)

